#!/usr/bin/env bash
# RKO Player - standalone Linux app installer (Steam Deck friendly). Runs in its own window, not a browser.
#   bash rko-player.sh            install (first run) and launch
#   bash rko-player.sh --install  install only
#   bash rko-player.sh --uninstall
# Needs internet once to fetch the Electron runtime (~100 MB), OR put electron-v*-linux-x64.zip next to this script.
set -u
APP=rko-player; DIR="$HOME/.local/share/$APP"; SELF="$(readlink -f "$0")"; HERE="$(dirname "$SELF")"
EV="${ELECTRON_VERSION:-33.2.0}"
EURL="${ELECTRON_URL:-https://github.com/electron/electron/releases/download/v$EV/electron-v$EV-linux-x64.zip}"

install_app(){
  mkdir -p "$DIR/app" "$DIR/electron" "$HOME/.local/share/applications"
  local n; n=$(awk '/^__PAYLOAD__$/{print NR+1; exit}' "$SELF")
  tail -n +"$n" "$SELF" | base64 -d > "$DIR/app/index.html" || { echo "Extract failed"; exit 1; }
  echo '{"name":"rko-player","version":"1.0.0","main":"main.js"}' > "$DIR/app/package.json"
  cat > "$DIR/app/preload.js" <<'JS'
const {ipcRenderer,webUtils}=require('electron');
window.rko={pathFor:f=>{try{return webUtils.getPathForFile(f)}catch(e){return ''}},allow:p=>ipcRenderer.sendSync('allow',p),save:(n,d)=>ipcRenderer.invoke('save',n,d),load:n=>ipcRenderer.invoke('load',n)};
JS
  cat > "$DIR/app/main.js" <<'JS'
const {app,BrowserWindow,ipcMain}=require('electron'),http=require('http'),fs=require('fs'),path=require('path');
app.commandLine.appendSwitch('autoplay-policy','no-user-gesture-required');
const allowed=new Set(),MT={mp4:'video/mp4',m4v:'video/mp4',mov:'video/quicktime',webm:'video/webm',mkv:'video/x-matroska','3gp':'video/3gpp',ogv:'video/ogg',avi:'video/x-msvideo',mp3:'audio/mpeg',wav:'audio/wav'};
ipcMain.on('allow',(e,p)=>{allowed.add(p);e.returnValue=1});
const sf=n=>path.join(app.getPath('userData'),'slot'+n+'.json');
ipcMain.handle('save',(e,n,d)=>{fs.mkdirSync(app.getPath('userData'),{recursive:true});fs.writeFileSync(sf(n),d||'')});
ipcMain.handle('load',(e,n)=>{try{return fs.readFileSync(sf(n),'utf8')}catch(x){return ''}});
const srv=http.createServer((q,r)=>{
 if(q.url.startsWith('/f?')){const p=new URL(q.url,'http://x').searchParams.get('p');
  if(!allowed.has(p)){r.writeHead(403);r.end();return}
  fs.stat(p,(e,st)=>{if(e){r.writeHead(404);r.end();return}
   let s=0,en=st.size-1,code=200;const h={'Accept-Ranges':'bytes','Content-Type':MT[path.extname(p).slice(1).toLowerCase()]||'application/octet-stream'},m=/bytes=(\d*)-(\d*)/.exec(q.headers.range||'');
   if(m){if(m[1]){s=+m[1];if(m[2])en=Math.min(+m[2],en)}else if(m[2]){s=Math.max(0,st.size-+m[2])}code=206;h['Content-Range']='bytes '+s+'-'+en+'/'+st.size}
   h['Content-Length']=en-s+1;r.writeHead(code,h);fs.createReadStream(p,{start:s,end:en}).pipe(r)});return}
 fs.readFile(path.join(__dirname,'index.html'),(e,d)=>{if(e){r.writeHead(500);r.end();return}r.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});r.end(d)})});
function open(port){const w=new BrowserWindow({fullscreen:true,backgroundColor:'#000000',autoHideMenuBar:true,title:'RKO Player',webPreferences:{preload:path.join(__dirname,'preload.js'),contextIsolation:false,sandbox:false}});w.setMenu(null);
 w.webContents.on('before-input-event',(e,i)=>{if(i.type!=='keyDown')return;if(i.key==='F11')w.setFullScreen(!w.isFullScreen());if(i.control&&i.key.toLowerCase()==='q')app.quit()});
 w.loadURL('http://127.0.0.1:'+port+'/')}
app.whenReady().then(()=>{srv.once('error',()=>srv.listen(0,'127.0.0.1',()=>open(srv.address().port)));srv.listen(47651,'127.0.0.1',()=>open(47651))});
app.on('window-all-closed',()=>app.quit());
JS
  if [ ! -x "$DIR/electron/electron" ]; then
    local zip; zip=$(ls "$HERE"/electron-v*-linux-x64.zip 2>/dev/null | head -n1)
    if [ -z "$zip" ]; then
      zip="$DIR/electron.zip"; echo "Downloading Electron $EV ..."
      if command -v curl >/dev/null; then curl -fL --progress-bar -o "$zip" "$EURL"; else wget -O "$zip" "$EURL"; fi || { echo "Download failed. Download electron-v$EV-linux-x64.zip from github.com/electron/electron/releases and put it next to this script."; exit 1; }
    fi
    if command -v unzip >/dev/null; then unzip -oq "$zip" -d "$DIR/electron"; else python3 -m zipfile -e "$zip" "$DIR/electron"; fi
    chmod +x "$DIR/electron/electron" "$DIR/electron/chrome_crashpad_handler" 2>/dev/null
    [ "$zip" = "$DIR/electron.zip" ] && rm -f "$zip"
  fi
  cat > "$DIR/rko-player.sh" <<L
#!/usr/bin/env bash
exec "$DIR/electron/electron" --no-sandbox --ozone-platform-hint=auto "$DIR/app" "\$@"
L
  chmod +x "$DIR/rko-player.sh"
  cat > "$HOME/.local/share/applications/$APP.desktop" <<D
[Desktop Entry]
Type=Application
Name=RKO Player
Comment=Retro TV station player
Exec=$DIR/rko-player.sh
Terminal=false
Categories=AudioVideo;Video;
D
  chmod +x "$HOME/.local/share/applications/$APP.desktop"
  [ -d "$HOME/Desktop" ] && cp "$HOME/.local/share/applications/$APP.desktop" "$HOME/Desktop/" && chmod +x "$HOME/Desktop/$APP.desktop"
  echo "Installed to $DIR"
}
case "${1:-}" in
  --uninstall) rm -rf "$DIR" "$HOME/.local/share/applications/$APP.desktop" "$HOME/Desktop/$APP.desktop"; echo removed; exit 0;;
  --install) install_app; exit 0;;
esac
install_app
exec "$DIR/rko-player.sh"
exit 0
